import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"平坦化与焦深","description":"","frontmatter":{"title":"平坦化与焦深","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/planarization-dof.md","filePath":"litho/planarization-dof.md","lastUpdated":1789023840000}'),E={name:"litho/planarization-dof.md"};function c(A,a,_,m,B,D){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="平坦化与焦深" tabindex="-1">平坦化与焦深 <a class="header-anchor" href="#平坦化与焦深" aria-label="Permalink to &quot;平坦化与焦深&quot;">​</a></h1><div class="epigraph"><p>瑞利焦深随 NA 平方收紧；晶圆上残留的台阶高度若不小于这笔预算，窗口在地形上先死，而不是在镜头上。</p><footer>—— 对照瑞利焦深与晶圆形貌预算；Mack / Levinson 对 DOF 与晶圆平坦度的叙述</footer></div><p><a href="/litho/cmp-topography">上一课</a>给出 CMP 地形。缺口是换算：这笔高度进不进本层焦深。<a href="/litho/rayleigh-litho">瑞利</a> 与 <a href="/litho/ed-process-window">E–D 窗</a> 已有 DOF 定义；本课钉平坦化预算，不重推 \\(k_2\\lambda/\\mathrm{NA}^2\\)。关键层对准如何在这张不平的饼上找网格，留给[下一课](/litho/critical-layer-alignment）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高 NA 浸没与 0.55 NA EUV 把可用焦深收到几十纳米量级（还要与随机窗求交）。晶圆翘曲、芯片台阶、胶厚变化、扫描机调平残差共享这笔预算。平坦化（CMP、旋涂、SOC）的价值是把地形的高频削到调平能跟、低频交给扫描机地图。剩余台阶 &gt; 有效 DOF，则场内必有失焦热点，LRC 在理想平面上绿灯也没用。</p><p>缺口是<strong>预算分账</strong>，不是再定义焦点。把所有 CD 离焦敏感都怪 PEB，会漏掉未抛平的前层。</p><h3 id="调平跟得上的频率" tabindex="-1">调平跟得上的频率 <a class="header-anchor" href="#调平跟得上的频率" aria-label="Permalink to &quot;调平跟得上的频率&quot;">​</a></h3><p>扫描机调平有空间带宽：场内多项式、狭缝方向平均。<a href="/litho/focus-sensor-topography">焦点传感器</a> 已写。CMP 波浪若落在带宽外，就是不可补偿地形。平坦化目标不是「绝对平」，是谱落在可补带内，且峰峰值进 DOF 分账。</p><p><span class="marginnote">胶厚本身占焦深。薄胶省焦深、损选择比。平坦化与硬掩模、胶厚选择是同一笔账的三页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分账：镜头/扫描 DOF 规格 − 胶厚 − 预期台阶 − 调平残差 − 动态 MSD 一类 = 余量。测量：产品晶圆焦点残差图对 CD。动作：加强 CMP、改 SOC、场内焦点校正、禁大台阶设计（密度窗）。High-NA 半场拼接区若有台阶，拼接课的套刻之外还要焦点。</p><p>余量为负时，先减台阶或改胶厚，再考虑加剂量硬撑随机窗——后者会伤吞吐。Mack 的 DOF 定义仍适用；本课只把晶圆地形从「忽略项」改写成分账行。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效成像平面随局部高度走。失焦引入像差型对比损失（已有课），NILS 下降，随机窗先关。地形与剂量耦合：厚胶区摆动曲线不同，CD 指纹像「假照明不均」。APC 若用全场平均焦点去补局部台阶，会牺牲另一侧。</p>',14)),(e(),s(d,null,{default:o(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOF%5B%22%E6%9C%89%E6%95%88%E7%84%A6%E6%B7%B1%22%5D%20--%3E%20BUD%5B%22%E5%88%86%E8%B4%A6%22%5D%0A%20%20STEP%5B%22CMP%20%2F%20%E8%8A%AF%E7%89%87%E5%8F%B0%E9%98%B6%22%5D%20--%3E%20BUD%0A%20%20PL%5B%22%E8%B0%83%E5%B9%B3%E5%B8%A6%E5%AE%BD%E5%86%85%E8%A1%A5%E5%81%BF%22%5D%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E5%8F%B0%E9%98%B6%22%5D%0A%20%20RES%20--%3E%20HOT%5B%22%E5%A4%B1%E7%84%A6%E7%83%AD%E7%82%B9%22%5D%0A%20%20BUD%20--%3E%20HOT%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>调平只吃带宽内的台阶；带外波浪直接进失焦热点。分账余量为负时，加剂量硬撑会先关掉随机窗。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不发明某机台未公开的 DOF 纳米数。不重写镜头像差。晶圆翘曲的应力源下一门过程控制会再收，本课只把它当高度谱的一项。</p><p>后课默认：焦深分账含地形；不可补的频率必须先平坦化。下一课对准在起伏表面上如何仍把关键层套准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平坦化把地形谱推进扫描机可补带，并留给焦深分账。</li><li>高 NA 下台阶从次要项变成窗口杀手。</li><li>假 CD 指纹可来自胶厚地形，不是照明。</li><li>出处：Mack 焦深；Levinson 晶圆平坦度；ASML 调平公开论述。</li></ul>',6))])}const P=r(E,[["render",c]]);export{u as __pageData,P as default};
